"""Locate a usable fastText engine and expose train()/test() over it.

Engine preference order:
  1. `import fasttext` already available (e.g. the prebuilt fasttext-wheel package,
      which is the authors' official fastText C++ 0.9.2 code with the pybind11 binding).
  2. `pip install fasttext-wheel` (prebuilt binary; Windows-safe) or `pip install fasttext`.
The training itself is always the authors' C++ implementation; this module only
forwards arguments verbatim. The engine provenance is recorded for metrics.json.
"""

import importlib
import importlib.metadata
import subprocess
import sys

_ENGINE_INFO = {"engine": None, "version": None}


def _describe() -> dict:
    for dist in ("fasttext-wheel", "fasttext"):
        try:
            version = importlib.metadata.version(dist)
            return {
                "engine": f"{dist} (official fastText C++ implementation, pybind11 binding)",
                "version": version,
            }
        except importlib.metadata.PackageNotFoundError:
            continue
    return {"engine": "fasttext (unknown distribution)", "version": None}


def get_engine():
    """Return (fasttext_module, info_dict); install a prebuilt wheel if necessary."""
    if _ENGINE_INFO["engine"] is not None:
        return importlib.import_module("fasttext"), dict(_ENGINE_INFO)
    try:
        mod = importlib.import_module("fasttext")
        _ENGINE_INFO.update(_describe())
        return mod, dict(_ENGINE_INFO)
    except ImportError:
        pass
    for pkg in ("fasttext-wheel", "fasttext"):
        print(f"[engine] fasttext not importable; attempting `pip install {pkg}`")
        try:
            subprocess.run([sys.executable, "-m", "pip", "install", pkg],
                           check=True, capture_output=True, text=True, timeout=900)
            mod = importlib.import_module("fasttext")
            _ENGINE_INFO.update(_describe())
            return mod, dict(_ENGINE_INFO)
        except Exception as exc:  # noqa: BLE001 - try the next distribution
            print(f"[engine] install of {pkg} failed: {exc}")
    raise RuntimeError(
        "No fastText engine available and none could be installed. "
        "The paper's system (authors' C++ fastText) requires the fasttext package."
    )


def train(fasttext_mod, input_path: str, *, lr: float, dim: int, wordNgrams: int,
          epoch: int, minCount: int, bucket: int, thread: int, loss: str,
          lrUpdateRate: int, minn: int, maxn: int, seed: int, verbose: int = 2):
    """One supervised training run with the authors' argument set (forwarded verbatim)."""
    return fasttext_mod.train_supervised(
        input=input_path,
        lr=lr,
        dim=dim,
        ws=5,                     # unused in supervised mode; fastText default
        epoch=epoch,
        minCount=minCount,
        minCountLabel=0,
        minn=minn,
        maxn=maxn,
        neg=5,                    # unused with softmax loss; fastText default
        wordNgrams=wordNgrams,
        loss=loss,
        bucket=bucket,
        thread=thread,
        lrUpdateRate=lrUpdateRate,
        t=1e-4,                   # unused in supervised mode; fastText default
        label="__label__",
        verbose=verbose,
        seed=seed,
    )


def test(model, test_path: str) -> dict:
    """Evaluate with the authors' C++ `test` (returns N, precision@1, recall@1)."""
    n, p_at_1, r_at_1 = model.test(test_path)
    return {"n": n, "precision_at_1": p_at_1, "recall_at_1": r_at_1,
            "accuracy_pct": 100.0 * p_at_1}

